INSERT INTO collection_pages VALUES('c20468c9046ed6b64f0156906d8af7d2064f3e2bc079bd716e20aa5f70938aaf','7a77ea6da5008e989c0c899b3157f19714fb83a9d1ac9df2bf21443950026d51','{"hasNext":false,"items":[{"author":{"account":{"login":"skrivan","providerType":"User"},"email":"skrivans@hotmail.com","name":"Sam Skrivan"},"authoredDate":"2026-02-06T20:02:46Z","committedDate":"2026-02-06T20:02:46Z","committer":{"account":{"login":"skrivan","providerType":"User"},"email":"skrivans@hotmail.com","name":"Sam Skrivan"},"observedAt":"2026-10-08T21:45:28.183Z","repositoryId":1151686564,"sha":"4dba914384162f300bab837d2b42901891ffc91a"},{"author":{"account":{"login":"skrivan","providerType":"User"},"email":"skrivans@hotmail.com","name":"Sam Skrivan"},"authoredDate":"2026-02-06T19:17:43Z","committedDate":"2026-02-06T19:17:43Z","committer":{"account":{"login":"skrivan","providerType":"User"},"email":"skrivans@hotmail.com","name":"Sam Skrivan"},"observedAt":"2026-10-08T21:45:28.183Z","repositoryId":1151686564,"sha":"47e1a7ba5957425bf511d0b06419662325769571"}],"observedAt":"2026-10-08T21:45:28.183Z","raw":[{"author":{"avatar_url":"https://avatars.githubusercontent.com/u/1320613?v=4","events_url":"https://api.github.com/users/skrivan/events{/privacy}","followers_url":"https://api.github.com/users/skrivan/followers","following_url":"https://api.github.com/users/skrivan/following{/other_user}","gists_url":"https://api.github.com/users/skrivan/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/skrivan","id":1320613,"login":"skrivan","node_id":"MDQ6VXNlcjEzMjA2MTM=","organizations_url":"https://api.github.com/users/skrivan/orgs","received_events_url":"https://api.github.com/users/skrivan/received_events","repos_url":"https://api.github.com/users/skrivan/repos","site_admin":false,"starred_url":"https://api.github.com/users/skrivan/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/skrivan/subscriptions","type":"User","url":"https://api.github.com/users/skrivan","user_view_type":"public"},"comments_url":"https://api.github.com/repos/skrivan/extensibleapp/commits/4dba914384162f300bab837d2b42901891ffc91a/comments","commit":{"author":{"date":"2026-02-06T20:02:46Z","email":"skrivans@hotmail.com","name":"Sam Skrivan"},"comment_count":0,"committer":{"date":"2026-02-06T20:02:46Z","email":"skrivans@hotmail.com","name":"Sam Skrivan"},"message":"Add sensor monitor page and fix Vite module federation loading\n\n- Replace energy overview template with sensor monitor page that shows\n  sensors grouped by floor with color-coded type badges and latest readings\n- Fix shell''s remote loader to support Vite federation ES module remotes\n  (dynamic import instead of script tag, /assets/ path, result normalization)\n- Share host React/ReactDOM via init(shareScope) to prevent dual instances\n- Make SDK ApiContext default fetch functional so isolated remotes can\n  call the API without the shell''s provider\n- Add index.html to page-template for Vite build support\n- Update dev script to build+preview (federation requires built output)\n\nCo-Authored-By: Claude Opus 4.6 <noreply@anthropic.com>","tree":{"sha":"6a563f01ed6a9dfe51039cfe8673684466760873","url":"https://api.github.com/repos/skrivan/extensibleapp/git/trees/6a563f01ed6a9dfe51039cfe8673684466760873"},"url":"https://api.github.com/repos/skrivan/extensibleapp/git/commits/4dba914384162f300bab837d2b42901891ffc91a","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/1320613?v=4","events_url":"https://api.github.com/users/skrivan/events{/privacy}","followers_url":"https://api.github.com/users/skrivan/followers","following_url":"https://api.github.com/users/skrivan/following{/other_user}","gists_url":"https://api.github.com/users/skrivan/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/skrivan","id":1320613,"login":"skrivan","node_id":"MDQ6VXNlcjEzMjA2MTM=","organizations_url":"https://api.github.com/users/skrivan/orgs","received_events_url":"https://api.github.com/users/skrivan/received_events","repos_url":"https://api.github.com/users/skrivan/repos","site_admin":false,"starred_url":"https://api.github.com/users/skrivan/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/skrivan/subscriptions","type":"User","url":"https://api.github.com/users/skrivan","user_view_type":"public"},"html_url":"https://github.com/skrivan/extensibleapp/commit/4dba914384162f300bab837d2b42901891ffc91a","node_id":"C_kwDORKVXpNoAKDRkYmE5MTQzODQxNjJmMzAwYmFiODM3ZDJiNDI5MDE4OTFmZmM5MWE","parents":[{"html_url":"https://github.com/skrivan/extensibleapp/commit/47e1a7ba5957425bf511d0b06419662325769571","sha":"47e1a7ba5957425bf511d0b06419662325769571","url":"https://api.github.com/repos/skrivan/extensibleapp/commits/47e1a7ba5957425bf511d0b06419662325769571"}],"sha":"4dba914384162f300bab837d2b42901891ffc91a","url":"https://api.github.com/repos/skrivan/extensibleapp/commits/4dba914384162f300bab837d2b42901891ffc91a"},{"author":{"avatar_url":"https://avatars.githubusercontent.com/u/1320613?v=4","events_url":"https://api.github.com/users/skrivan/events{/privacy}","followers_url":"https://api.github.com/users/skrivan/followers","following_url":"https://api.github.com/users/skrivan/following{/other_user}","gists_url":"https://api.github.com/users/skrivan/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/skrivan","id":1320613,"login":"skrivan","node_id":"MDQ6VXNlcjEzMjA2MTM=","organizations_url":"https://api.github.com/users/skrivan/orgs","received_events_url":"https://api.github.com/users/skrivan/received_events","repos_url":"https://api.github.com/users/skrivan/repos","site_admin":false,"starred_url":"https://api.github.com/users/skrivan/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/skrivan/subscriptions","type":"User","url":"https://api.github.com/users/skrivan","user_view_type":"public"},"comments_url":"https://api.github.com/repos/skrivan/extensibleapp/commits/47e1a7ba5957425bf511d0b06419662325769571/comments","commit":{"author":{"date":"2026-02-06T19:17:43Z","email":"skrivans@hotmail.com","name":"Sam Skrivan"},"comment_count":0,"committer":{"date":"2026-02-06T19:17:43Z","email":"skrivans@hotmail.com","name":"Sam Skrivan"},"message":"Initial commit: extensible platform prototype\n\nPlugin-based React app where power users build custom pages using Claude Code,\nan SDK, and an MCP server. Pages are dynamically loaded via Module Federation.\n\n- shell: React + Vite host app with sidebar nav, dynamic remote loader, error\n  boundaries, Express API server wrapping SQLite\n- sdk: @yourco/sdk with 7 UI components (PageLayout, BuildingSelector, Card,\n  StatCard, DataTable, Badge, LoadingSpinner), 5 data hooks, auth/api contexts\n- mcp-server: 9 MCP tools for building/sensor/energy/alert data discovery,\n  SQLite seed script generating 8 buildings with 90 days of synthetic data\n- page-template: starter repo for power users with Module Federation config,\n  example page, CLAUDE.md instructions, and MCP server pre-configured\n\nCo-Authored-By: Claude Opus 4.6 <noreply@anthropic.com>","tree":{"sha":"64a9de955b6034f31fe22664d6c0e73f8d4f3329","url":"https://api.github.com/repos/skrivan/extensibleapp/git/trees/64a9de955b6034f31fe22664d6c0e73f8d4f3329"},"url":"https://api.github.com/repos/skrivan/extensibleapp/git/commits/47e1a7ba5957425bf511d0b06419662325769571","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/1320613?v=4","events_url":"https://api.github.com/users/skrivan/events{/privacy}","followers_url":"https://api.github.com/users/skrivan/followers","following_url":"https://api.github.com/users/skrivan/following{/other_user}","gists_url":"https://api.github.com/users/skrivan/gists{/gist_id}","gravatar_id":"","html_url":"https://github.